import logging import sys from datetime import datetime
class TkinterLogger: """Enhanced logging for Tkinter applications."""
def __init__(self, log_file="tkinter_debug.log"): self.logger = logging.getLogger('TkinterApp') self.logger.setLevel(logging.DEBUG)
# Create formatters file_formatter = logging.Formatter( '%(asctime)s - %(name)s - %(levelname)s - %(funcName)s:%(lineno)d - %(message)s' ) console_formatter = logging.Formatter( '%(levelname)s - %(message)s' )
# File handler file_handler = logging.FileHandler(log_file) file_handler.setLevel(logging.DEBUG) file_handler.setFormatter(file_formatter)
# Console handler console_handler = logging.StreamHandler(sys.stdout) console_handler.setLevel(logging.INFO) console_handler.setFormatter(console_formatter)
# Add handlers self.logger.addHandler(file_handler) self.logger.addHandler(console_handler)
def log_widget_event(self, widget, event_type, event_data=None): """Log Tkinter widget events.""" message = f"Widget {widget.winfo_class()}: {event_type}" if event_data: message += f" - {event_data}" self.logger.debug(message)
def log_autocad_operation(self, operation, parameters=None, result=None): """Log AutoCAD operations.""" message = f"AutoCAD Operation: {operation}" if parameters: message += f" - Params: {parameters}" if result: message += f" - Result: {result}" self.logger.info(message)
def log_error_with_traceback(self, error, context=""): """Log errors with full traceback.""" self.logger.error(f"Error in {context}: {error}") self.logger.error("Traceback:", exc_info=True)
# Usage in Tkinter app logger = TkinterLogger()
def on_button_click(): logger.log_widget_event(self.button, "clicked") try: logger.log_autocad_operation("create_line", {"start": (0,0), "end": (100,100)}) # Perform operation result = create_line((0,0), (100,100)) logger.log_autocad_operation("create_line", result=result) except Exception as e: logger.log_error_with_traceback(e, "button_click")

